void data_logging_csv_from_char_arr()
{
  while (true)
  {
    if (uBit.buttonA.wasPressed())
    {
        uBit.display.scroll("Logging");
        uBit.log.clear();
        uBit.log.logString(logData);
        uBit.display.scroll("Ready");
    }
    // Prevent falling off end of program as it is confusing.
  }
}
